/// (smallest, largest, total), or (0, 0, 0) for an empty list.
fn stats(barrels: &[i32]) -> (i32, i32, i32) {
    if barrels.is_empty() {
        return (0, 0, 0);
    }
    let mut low = barrels[0];
    let mut high = barrels[0];
    let mut total = 0;
    for &n in barrels {
        low = low.min(n);
        high = high.max(n);
        total += n;
    }
    (low, high, total)
}

/// The counts strictly greater than limit, in order.
fn above(barrels: &[i32], limit: i32) -> Vec<i32> {
    barrels.iter().copied().filter(|n| *n > limit).collect()
}

fn main() {
    let barrels = vec![3, 9, 4];
    let (low, high, total) = stats(&barrels);
    println!("{low} {high} {total}");
    println!("{:?}", above(&barrels, 3));
}

