/// Total hours stood by `name`.
fn hours_for(watches: &[(&str, u32)], name: &str) -> u32 {
    let mut total = 0;
    for &(who, hours) in watches {
        if who == name {
            total += hours;
        }
    }
    total
}

/// The name on the longest single watch (first one on a tie).
fn busiest<'a>(watches: &[(&'a str, u32)]) -> Option<&'a str> {
    let mut best: Option<(&'a str, u32)> = None;
    for &(who, hours) in watches {
        match best {
            Some((_, most)) if most >= hours => {}
            _ => best = Some((who, hours)),
        }
    }
    match best {
        Some((who, _)) => Some(who),
        None => None,
    }
}

/// Distinct names, sorted, joined with ", ".
fn roster(watches: &[(&str, u32)]) -> String {
    let mut names: Vec<&str> = Vec::new();
    for &(who, _) in watches {
        if !names.contains(&who) {
            names.push(who);
        }
    }
    names.sort();
    names.join(", ")
}

fn main() {
    let watches = vec![("Anne", 4), ("Jack", 6), ("Anne", 2), ("Mary", 6)];
    println!("{}", hours_for(&watches, "Anne"));
    println!("{:?}", busiest(&watches));
    println!("{}", roster(&watches));
}

