fn top_three(scores: &[u32]) -> Vec<u32> {
    let mut sorted = scores.to_vec();
    sorted.sort_by(|a, b| b.cmp(a));
    sorted.truncate(3);
    sorted
}

fn above_average(scores: &[u32]) -> usize {
    if scores.is_empty() {
        return 0;
    }
    let total: u64 = scores.iter().map(|&s| u64::from(s)).sum();
    let n = scores.len() as u64;
    // s > total / n, without rounding: s * n > total
    scores.iter().filter(|&&s| u64::from(s) * n > total).count()
}

fn main() {
    println!("{:?}", top_three(&[5, 9, 9, 1]));
    println!("{}", above_average(&[1, 2]));
}

