use std::io::{self, Read};

/// "name age" -> Some((name, age)); anything else -> None.
fn parse_sailor(line: &str) -> Option<(&str, u32)> {
    let words: Vec<&str> = line.split_whitespace().collect();
    if words.len() != 2 {
        return None;
    }
    match words[1].parse() {
        Ok(age) => Some((words[0], age)),
        Err(_) => None,
    }
}

fn main() {
    let mut text = String::new();
    io::stdin().read_to_string(&mut text).unwrap();

    let mut crew: Vec<(&str, u32)> = Vec::new();
    let mut blotted = 0;
    for line in text.lines() {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }
        match parse_sailor(line) {
            Some(sailor) => crew.push(sailor),
            None => blotted += 1,
        }
    }

    println!("crew: {}", crew.len());
    println!("blotted: {blotted}");

    let mut oldest: Option<(&str, u32)> = None;
    for &(name, age) in &crew {
        match oldest {
            Some((_, best)) if best >= age => {}
            _ => oldest = Some((name, age)),
        }
    }
    match oldest {
        Some((name, age)) => println!("oldest: {name} ({age})"),
        None => println!("oldest: none"),
    }

    if crew.is_empty() {
        println!("average age: none");
        println!("roster: none");
    } else {
        let total: u64 = crew.iter().map(|&(_, age)| u64::from(age)).sum();
        let average = total as f64 / crew.len() as f64;
        println!("average age: {average:.1}");
        let mut names: Vec<&str> = crew.iter().map(|&(name, _)| name).collect();
        names.sort();
        println!("roster: {}", names.join(", "));
    }
}
